import { useMemo } from 'react';

function CalendarView() {
  const today = new Date();
  const year = today.getFullYear();
  const month = today.getMonth();

  const firstDay = new Date(year, month, 1);
  const lastDay = new Date(year, month + 1, 0);
  const startOffset = (firstDay.getDay() + 6) % 7;
  const totalDays = lastDay.getDate();

  const days = useMemo(() => {
    const cells = [];

    for (let i = 0; i < startOffset; i += 1) {
      cells.push({ key: `empty-${i}`, day: '', isCurrentMonth: false });
    }

    for (let day = 1; day <= totalDays; day += 1) {
      const date = new Date(year, month, day);
      cells.push({
        key: `day-${day}`,
        day,
        isCurrentMonth: true,
        isToday: date.toDateString() === today.toDateString(),
      });
    }

    while (cells.length % 7 !== 0) {
      cells.push({ key: `extra-${cells.length}`, day: '', isCurrentMonth: false });
    }

    return cells;
  }, [month, startOffset, totalDays, today, year]);

  const weekdays = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
  const monthName = today.toLocaleString('default', { month: 'long', year: 'numeric' });

  return (
    <section className="panel working-page">
      <p className="dashboard-label">Schedule</p>
      <h2>{monthName}</h2>
      <p>Keep track of your planned work and key dates.</p>

      <div style={{ marginTop: '20px' }}>
        <div className="metric-grid" style={{ gridTemplateColumns: 'repeat(7, minmax(0, 1fr))', gap: '8px' }}>
          {weekdays.map((day) => (
            <div key={day} style={{ textAlign: 'center', fontSize: '12px', color: '#6d7d88', padding: '10px 0' }}>
              {day}
            </div>
          ))}

          {days.map((cell) => (
            <div
              key={cell.key}
              style={{
                minHeight: '72px',
                border: '1px solid #f0dfd0',
                borderRadius: '8px',
                background: cell.isToday ? '#ffe4d5' : '#fffdf9',
                display: 'flex',
                alignItems: 'flex-start',
                justifyContent: 'flex-start',
                padding: '8px',
                color: cell.isCurrentMonth ? '#30495a' : '#b0b9bf',
                fontWeight: cell.isToday ? 700 : 500,
              }}
            >
              {cell.day || ''}
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

export default CalendarView;
